    "Aceitar mensagens de grupos, canais e comunidades — desligue para receber só a conversa direta com o número da live": "Принимать сообщения из групп, каналов и сообществ — выключите, чтобы получать только личную переписку с номером трансляции",
    "Só a conversa direta está entrando — ligue os grupos acima para usar este campo.": "Проходит только личная переписка — включите группы выше, чтобы пользоваться этим полем.",
