    "📱 O código em si": "📱 Сам код",
    "As cores acima são do cartão que segura o QR; estas aqui são do código em si. Nada disto muda o que o QR carrega — só o desenho.": "Цвета выше — у карточки, которая держит QR; эти — у самого кода. Ничто из этого не меняет то, что несёт QR, — только рисунок.",
