    "A cada 10 minutos": "Каждые 10 минут",
    "A cada 15 minutos": "Каждые 15 минут",
    "A cada 20 minutos": "Каждые 20 минут",
    "A cada 30 minutos": "Каждые 30 минут",
    "A cada 45 minutos": "Каждые 45 минут",
    "A cada 60 minutos": "Каждые 60 минут",
    "Recarregar reinicia a conexão de cada rede e": "Обновление перезапускает подключение каждой сети и",
    "busca de volta os comentários que a plataforma ainda guarda": "возвращает комментарии, которые площадка ещё хранит",
    "— é assim que o buraco deixado por um engasgo da conexão se fecha sozinho. As redes são recarregadas uma de cada vez, com folga entre elas. Cada coluna também tem um botão 🔄 para recarregar só ela, na hora que você quiser.": "— так пробел, оставшийся от сбоя связи, закрывается сам собой. Сети обновляются по очереди, с паузой между ними. У каждой колонки также есть кнопка 🔄, чтобы обновить только её, когда вам нужно.",
    "Recarregar todas as redes conectadas e buscar os comentários antigos de volta": "Обновить все подключённые сети и вернуть старые комментарии",
    "Recarregar esta rede e buscar os comentários antigos de volta": "Обновить эту сеть и вернуть старые комментарии",
