    "Voltar ao tema padrão do OBS Social? As cores e ajustes que você mudou aqui serão descartados.": "Вернуться к стандартной теме OBS Social? Изменённые здесь цвета и настройки будут сброшены.",
    "Não consegui ler esse arquivo de tema. Ele precisa ser um tema salvo pelo OBS Social.": "Не удалось прочитать этот файл темы. Это должна быть тема, сохранённая в OBS Social.",
    "Carregar este tema? Ele substitui as cores e os ajustes de aparência que estão valendo agora.": "Загрузить эту тему? Она заменит действующие сейчас цвета и настройки внешнего вида.",
