    'Idioma do sistema': 'Язык системы',
    '🌐 Idioma': '🌐 Язык',
    'Idioma da interface': 'Язык интерфейса',
    'Escolha o idioma do OBS Social. "Idioma do sistema" segue o idioma do navegador/computador de quem abre cada página. A mudança vale para o painel, as configurações e os overlays — na hora, sem reiniciar.':
      'Выбери язык OBS Social. «Язык системы» подстраивается под язык браузера/компьютера того, кто открывает каждую страницу. Изменение действует на панель, настройки и оверлеи — сразу, без перезапуска.',
    'O que não tiver tradução aparece em português. Textos escritos por você ou pelos espectadores (nomes, mensagens do chat, títulos dos widgets) nunca são traduzidos.':
      'Всё, для чего нет перевода, показывается на португальском. Тексты, написанные тобой или зрителями (имена, сообщения чата, названия виджетов), никогда не переводятся.',

