      'С паролем любой, кто открывает панель по сети, может войти с ним и управлять всем (переключатели выше действуют на тех, кто НЕ вошёл). Пароль превращается в зашифрованный код (хеш) — он никогда не хранится текстом. Только этот компьютер может его установить, сменить или удалить.',
    'senha atual (para trocar/remover)': 'текущий пароль (чтобы сменить/удалить)',
    'nova senha (mín. 4 caracteres)': 'новый пароль (мин. 4 символа)',
    'Definir/trocar a senha': 'Установить/сменить пароль',
    'Remover a senha': 'Удалить пароль',
    'A senha precisa ter pelo menos 4 caracteres.': 'Пароль должен быть не короче 4 символов.',
    'Remover a senha? A rede volta a poder usar só o que os seletores liberarem.': 'Удалить пароль? Сеть снова сможет использовать только то, что разрешают переключатели.',
    'Desligar a restrição = LIBERDADE TOTAL. Qualquer pessoa na sua rede/Wi-Fi vai poder controlar o programa inteiro, sem senha. Tem certeza?':
      'Выключить ограничение = ПОЛНАЯ СВОБОДА. Любой человек в твоей сети/Wi-Fi сможет управлять всей программой, без пароля. Точно?',
    '🔒 Modo seguro: quem entra pela rede só assiste ao painel e usa o que você liberar nos seletores abaixo.': '🔒 Безопасный режим: кто заходит по сети, только смотрит панель и пользуется тем, что ты разрешишь переключателями ниже.',
    '⚠️ Liberdade total: qualquer pessoa conectada na sua rede/Wi-Fi controla o programa inteiro, sem senha. Use só em redes que você confia de verdade.':
      '⚠️ Полная свобода: любой, кто подключён к твоей сети/Wi-Fi, управляет всей программой, без пароля. Используй только в сетях, которым по-настоящему доверяешь.',
    '🖥️ Máquinas conectadas agora': '🖥️ Подключённые сейчас машины',
    'ninguém conectado': 'никто не подключён',
    'Só este computador está conectado agora — ninguém mais está acessando.': 'Сейчас подключён только этот компьютер — больше никто не заходит.',
    'aparelho desconhecido': 'неизвестное устройство',
    'não encontrei um IP de rede neste computador': 'не нашёл сетевой IP на этом компьютере',
    'Reiniciar o OBS Social agora? Ele fecha e abre sozinho em alguns segundos; o overlay no OBS reconecta sem você fazer nada.':
      'Перезапустить OBS Social сейчас? Он закроется и откроется сам за несколько секунд; оверлей в OBS переподключится без твоего участия.',
    '♻️ Reiniciando o OBS Social... esta página recarrega em instantes.': '♻️ Перезапускаю OBS Social... эта страница перезагрузится через мгновение.',
