    "nome": "имя",
    "🖥️ 1920×1080 (Full HD)": "🖥️ 1920×1080 (Full HD)",
    "🖥️ 1280×720 (HD)": "🖥️ 1280×720 (HD)",
    "🖥️ 2560×1440 (2K)": "🖥️ 2560×1440 (2K)",
    "🖥️ 3840×2160 (4K)": "🖥️ 3840×2160 (4K)",
    "🖥️ 3440×1440 (ultrawide)": "🖥️ 3440×1440 (ультраширокий)",
    "📱 1080×1920 (vertical)": "📱 1080×1920 (вертикальный)",
    "📱 720×1280 (vertical)": "📱 720×1280 (вертикальный)",
    "Deixe o OBS Social com a sua cara: cores, imagem de fundo, tamanhos de texto e de ícones, cantos e espaçamento. Isto muda o": "Сделайте OBS Social своим: цвета, фоновое изображение, размеры текста и значков, углы и отступы. Это меняет",
    "painel e as configurações": "панель и настройки",
    "— e, com o 🖥️ abaixo ligado, os": "— а с включённым 🖥️ ниже",
    "overlays da live": "оверлеи эфира",
    "vestem o tema junto. O": "тоже одеваются в тему.",
    "(no painel) continua funcionando por cima disto, para aumentar tudo de uma vez.": "(в панели) продолжает работать поверх, чтобы увеличить всё сразу.",
    "Vestir também os overlays da live": "Одевать и оверлеи эфира",
    "— ao carregar um tema, o cartão do destaque, o chat fixo e os widgets ganham as cores, os cantos e a fonte dele (o QR mantém o fundo branco, para continuar escaneável)": "— при загрузке темы карточка, закреплённый чат и виджеты берут её цвета, углы и шрифт (QR сохраняет белый фон, чтобы оставаться сканируемым)",
    "Acessibilidade": "Доступность",
    "♿ Acessibilidade": "♿ Доступность",
    "Recursos para o OBS Social funcionar bem para todo mundo. Cada um tem o seu liga/desliga e vale no": "Функции, чтобы OBS Social хорошо работал для всех. У каждой свой переключатель, действует в",
    "painel e nas configurações": "панели и настройках",
    "na hora, em todos os aparelhos conectados. Os overlays do OBS (o conteúdo que o público vê) ficam como você desenhou.": "мгновенно, на всех подключённых устройствах. Оверлеи OBS (контент для зрителей) остаются такими, какими вы их сделали.",
    "Contraste reforçado": "Усиленный контраст",
    "— textos secundários e bordas deixam de ser suaves; links ganham sublinhado": "— вторичные тексты и рамки перестают быть мягкими; ссылки подчёркиваются",
    "Para baixa visão. Combina com o tema ⚡ Alto contraste da aba 🎨 Temas (preto + amarelo), que muda as cores da interface inteira.": "Для слабого зрения. Сочетается с темой ⚡ Высокий контраст во вкладке 🎨 Темы (чёрный + жёлтый), меняющей цвета всего интерфейса.",
    "Reduzir animações": "Меньше анимаций",
    "— corta as animações e transições da interface": "— убирает анимации и переходы интерфейса",
    "Para quem tem sensibilidade a movimento (enjoo, epilepsia fotossensível, TDAH). As animações do overlay na live não mudam — elas são parte do seu show.": "Для чувствительности к движению (укачивание, фоточувствительная эпилепсия, СДВГ). Анимации оверлея в эфире не меняются — это часть вашего шоу.",
    "Foco visível reforçado": "Заметный фокус",
    "— um anel grosso mostra onde você está ao navegar por Tab": "— толстое кольцо показывает, где вы при навигации Tab",
    "Para quem usa o teclado em vez do mouse (mobilidade reduzida, leitores de tela).": "Для тех, кто пользуется клавиатурой вместо мыши (ограниченная подвижность, скринридеры).",
    "Formas além de cor no status": "Формы вдобавок к цвету в статусе",
    "— a bolinha das conexões ganha ✓ (live no ar), ! (sem live) e ✕ (falhou)": "— точка подключения получает ✓ (эфир идёт), ! (эфира нет) и ✕ (сбой)",
    "Para daltonismo: verde, amarelo e vermelho deixam de ser a única pista.": "Для дальтонизма: зелёный, жёлтый и красный перестают быть единственной подсказкой.",
    "💡 Também ajudam (já existem em outras abas)": "💡 Тоже помогают (уже есть в других вкладках)",
    "(no painel) amplia tudo de uma vez; o": "(в панели) увеличивает всё сразу;",
    "Tamanho dos textos": "Размер текста",
    "e a": "и",
    "fonte": "шрифт",
    "ficam na aba 🎨 Temas; os avisos importantes aparecem como texto (nunca só como som); e as dicas dos botões são lidas por leitores de tela. Falta algo para você? Conte na aba 📣 Feedback — acessibilidade é prioridade.": "находятся во вкладке 🎨 Темы; важные предупреждения выводятся текстом (никогда только звуком); подсказки кнопок читаются скринридерами. Чего-то не хватает? Напишите во вкладке 📣 Отзывы — доступность в приоритете.",
    "A conexão falhou": "Сбой подключения",
    "🎁 Resultado do sorteio": "🎁 Результат розыгрыша",
    "O pódio também está na tela do OBS (widget 🎁). Fechar aqui não tira de lá.": "Подиум также на экране OBS (виджет 🎁). Закрытие здесь его там не убирает.",
    "Fechar este aviso aqui (a tela do OBS continua como está)": "Закрыть это уведомление здесь (экран OBS остаётся как есть)",

    // ---------- v0.44.0: 8 alças, chat fixo no mapa e o crachá 🔢 ----------
    "e puxe qualquer uma das": "и потяните любую из",
    "8 alças": "8 ручек",
    "para mudar o tamanho — os números aparecem ao vivo, na mesma unidade dos seletores manuais. O 📺": "чтобы изменить размер — числа показываются вживую, в той же единице, что и ручные регуляторы.",
    "Chat fixo": "Закреплённый чат",
    "também mora aqui (ele é a URL própria dele no OBS, então a prévia não o desenha — mas a posição e o tamanho valem de verdade). Seu overlay enviado (moldura de tela inteira) aparece como 🖼️.": "тоже живёт здесь (это его собственный URL в OBS, поэтому предпросмотр его не рисует — но позиция и размер действуют по-настоящему). Ваш загруженный оверлей (полноэкранная рамка) показан как 🖼️.",
    "Altura:": "Высота:",
