    "Encerrar transmissão": "Закончить трансляцию",
    "Gravar": "Записывать",
    "Parar gravação": "Остановить запись",
    "Cenas (escolhe o preview 👁)": "Сцены (выбирает превью 👁)",
    "Cenas (troca direto no ar)": "Сцены (меняет сразу в эфире)",
    "🟢 conectado": "🟢 подключено",
    "🟡 procurando o OBS...": "🟡 ищу OBS...",
    "📡 AO VIVO": "📡 В ЭФИРЕ",
    "📡 fora do ar": "📡 вне эфира",
    "⏺ gravando": "⏺ идёт запись",
    "⏺ parado": "⏺ остановлено",
    "Encerrar a TRANSMISSÃO no OBS agora? A live sai do ar.": "Закончить ТРАНСЛЯЦИЮ в OBS сейчас? Эфир прекратится.",
    "Iniciar a TRANSMISSÃO no OBS agora? Você entra AO VIVO.": "Начать ТРАНСЛЯЦИЮ в OBS сейчас? Вы выходите В ЭФИР.",
    "Parar a gravação no OBS?": "Остановить запись в OBS?",
    "Começar a gravar no OBS?": "Начать запись в OBS?",
