    "🔴 o OBS pede senha — copie a senha em Ferramentas → Configurações do Servidor WebSocket": "🔴 OBS просит пароль — скопируйте его в Инструменты → Настройки сервера WebSocket",
    "🔴 senha do OBS errada — confira em Ferramentas → Configurações do Servidor WebSocket": "🔴 неверный пароль OBS — проверьте Инструменты → Настройки сервера WebSocket",
