    "✏️ Modo ordenar: arraste um botão sobre o outro para trocar de lugar. Clique no ✏️ de novo para voltar a tocar.": "✏️ Режим порядка: перетащите кнопку на другую, чтобы поменять их местами. Нажмите ✏️ ещё раз, чтобы вернуться к игре.",
