    "A escala do OBS vai de -100 dB (mudo) a +26 dB. 0 dB é o volume cheio da fonte.": "Шкала OBS идёт от -100 дБ (тишина) до +26 дБ. 0 дБ — источник на полной громкости.",
    "Em milissegundos (1000 = 1 segundo). 0 = não mexe na duração que já está no OBS.": "В миллисекундах (1000 = 1 секунда). 0 = не трогает длительность, уже заданную в OBS.",
    "Escolha o que esta tecla faz no OBS. As listas de cenas, fontes e filtros vêm do OBS conectado — sem conexão, dá para digitar o nome na mão.": "Выберите, что эта клавиша делает в OBS. Списки сцен, источников и фильтров приходят из подключённого OBS — без подключения имя можно ввести вручную.",
    "🎵 toca um som · 🎬 Ação do OBS: comanda o OBS Studio (gravar, trocar de cena, mudo...) · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 играет звук · 🎬 Действие OBS: управляет OBS Studio (запись, смена сцены, отключение звука...) · 🎛️ Кнопка мультидействия: хранит клавиши, а щелчок проигрывает всё по очереди (удержание открывает) · 📁 Простая папка: только хранит клавиши — щелчок открывает, ничего не играет",
