    "🎛️ Criar teclas do vMix na Mesa (escolha o que quiser)": "🎛️ Создать клавиши vMix на Пульте (на выбор)",
    "Conecte o 🎛️ vMix (página vMix Remoto) para listar os recursos dele aqui.": "Подключите 🎛️ vMix (страница vMix удалённо), чтобы увидеть его ресурсы здесь.",
