    "Pílula colorida (padrão)": "Цветная плашка (по умолчанию)",
    "Texto simples (como nome e texto)": "Простой текст (как имя и текст)",
    "Centralizar na tela (leva este overlay para o meio do canvas)": "Центрировать на экране (переносит этот оверлей в середину холста)",
    "Centralizar na tela (leva esta peça para o meio do canvas)": "Центрировать на экране (переносит эту деталь в середину холста)",
    "Na live, este comentário vestiria o molde": "В эфире этот комментарий надел бы шаблон",
    "A prévia mostra o visual ao vivo, que é o que você está editando — para ajustar o molde, abra-o no seletor 🎭 Editando.": "Предпросмотр показывает живой вид, который вы и редактируете — чтобы настроить шаблон, откройте его в селекторе 🎭 Редактирование.",
    "Clique num overlay ou numa peça para ver e digitar as medidas dele.": "Нажмите на оверлей или деталь, чтобы увидеть и ввести её размеры.",
    "🧩 Clique numa peça do mapa para ajustá-la aqui (tamanho, caixa, giro, opacidade, cor...).": "🧩 Нажмите на деталь на карте, чтобы настроить её здесь (размер, рамка, поворот, прозрачность, цвет...).",
    "👤 Avatar": "👤 Аватар",
    "📛 Nome": "📛 Имя",
    "Tamanho da letra": "Размер шрифта",
    "💬 Texto do comentário": "💬 Текст комментария",
