    "Letras do exemplo": "Букв в примере",
    "💰 Valor do Super Chat": "💰 Сумма Super Chat",
    "Camada": "Слой",
    "— escolha um perfil —": "— выберите профиль —",
    "Há mudanças não salvas. Trocar de perfil e descartá-las?": "Есть несохранённые изменения. Сменить профиль и отбросить их?",
    "Descartar as mudanças não salvas e recarregar o perfil?": "Отбросить несохранённые изменения и перезагрузить профиль?",
