    "Já tem uma restauração em andamento — espere ela terminar.": "Восстановление уже идёт — дождитесь окончания.",
    "O navegador bloqueou a janela do download — libere as pop-ups deste endereço.": "Браузер заблокировал окно загрузки — разрешите всплывающие окна для этого адреса.",
    "esse arquivo não é um backup da Mesa": "этот файл не бэкап Пульта",
    "o mesa.json de dentro do backup está ilegível": "файл mesa.json внутри бэкапа не читается",
