    "arquivo não reconhecido": "файл не распознан",
    "O programa respondeu de um jeito que não entendi.": "Программа ответила так, что я не понял.",
    "Modo restrito: área de transferência desativada pelo streamer.": "Ограниченный режим: буфер обмена выключен стримером.",
    "Arquivo grande demais para quem entra pela rede (limite: 300 MB). No computador do streamer não há limite.": "Файл слишком велик для входящих по сети (предел: 300 МБ). На компьютере стримера предела нет.",
    "O disco está quase cheio — libere espaço antes de compartilhar arquivos.": "Диск почти заполнен — освободите место перед тем, как делиться файлами.",
    "O disco encheu durante o envio — o arquivo não foi guardado.": "Диск заполнился во время отправки — файл не сохранён.",
    "Muitas tentativas ao mesmo tempo. Espere um instante.": "Слишком много попыток сразу. Подождите немного.",
    // ---------- v0.91.0: janelas que lembram o lugar ----------
    "Voltar esta janela ao lugar e ao tamanho padrão": "Вернуть это окно на место и к размеру по умолчанию",
    "Voltar esta janela ao lugar padrão": "Вернуть это окно на место по умолчанию",
    "Encaixar de volta na barra de ferramentas (e esquecer o lugar guardado)": "Вернуть на панель инструментов (и забыть сохранённое место)",
    "Arraste para mover · estique pelo canto inferior direito · o lugar fica guardado": "Тяните, чтобы двигать · растягивайте за нижний правый угол · место запоминается",
    // ---------- v0.92.0: arte do perfil na barra e tira de moldes ----------
    "🖼️ Arte deste perfil": "🖼️ Графика этого профиля",
    "Envia a imagem ou o vídeo que vai ser o fundo deste perfil. Com um nome escrito ao lado, a arte espera e entra junto no ➕ Novo perfil; sem nome, ela veste na hora o molde que está aberto": "Загрузите изображение или видео, которое станет фоном этого профиля. Если рядом вписано имя, графика подождёт и войдёт вместе с ➕ Новый профиль; без имени она сразу оденет открытый шаблон",
    "arte à espera do perfil novo": "графика ждёт новый профиль",
    "Desistir desta arte (o arquivo continua na sua biblioteca)": "Отказаться от этой графики (файл останется в вашей библиотеке)",
    "🎭 Cada perfil com a arte dele": "🎭 Каждый профиль со своей графикой",
    "Abrir este molde no editor para ajustar": "Открыть этот шаблон в редакторе для настройки",
    "Voltar ao visual ao vivo do destaque": "Вернуться к живому виду выделенного",
    "Visual ao vivo": "Живой вид",
    "sem arte": "без графики",
    // ---------- v0.93.0: a arte é independente do cartão ----------
    "Arraste para esticar a arte — ela é independente do cartão padrão e pode passar dele (até 400%)": "Тяните, чтобы растянуть графику — она независима от стандартной карточки и может выходить за неё (до 400%)",
    // ---------- v0.94.0: peças soltas, 🎯 foco e 📋 copiar ajustes ----------
    "🎯 Só o que estou editando": "🎯 Только то, что я редактирую",
    "Some com todo o resto do mapa e deixa só o overlay que você está editando (com as peças dele). É só aqui no editor: a live continua mostrando tudo.": "Скрывает всё остальное на карте и оставляет только тот оверлей, который вы редактируете (с его частями). Только в редакторе: в эфире по-прежнему видно всё.",
    "📋 Copiar ajustes para...": "📋 Скопировать настройки в...",
    "Leva os ajustes deste molde (posições, tamanhos e peças) para outros moldes — cada um fica com a arte dele": "Переносит настройки этого шаблона (положения, размеры и части) в другие шаблоны — у каждого остаётся своя графика",
    "Copiar ajustes do molde": "Скопировать настройки шаблона",
