    "Levar a arte junto (troca a arte dos moldes marcados pela deste)": "Взять графику с собой (заменяет графику отмеченных шаблонов на эту)",
    "Arraste para esticar a peça — ela é independente do cartão padrão e pode passar dele (até 400%)": "Тяните, чтобы растянуть часть — она независима от стандартной карточки и может выходить за неё (до 400%)",
    "Arraste para mudar o tamanho da peça — ela pode passar do cartão padrão (até 1000%)": "Тяните, чтобы изменить размер части — она может выходить за стандартную карточку (до 1000%)",
    "Fora do foco 🎯 — clique para editar este overlay": "Вне фокуса 🎯 — нажмите, чтобы редактировать этот оверлей",
    "automático": "автоматически",
    "0 = automático (a peça fica do tamanho do conteúdo dela)": "0 = автоматически (размер части по её содержимому)",
