    // 🎞️ v0.129: mídia direta (URL ou arquivo do computador, direto para a tela)
    "Mídia direta: imagem, vídeo ou áudio de uma URL ou do computador": "Прямое медиа: изображение, видео или аудио по URL или с компьютера",
    "🎞️ Mídia direta": "🎞️ Прямое медиа",
    "Cole a URL (YouTube, TikTok, Instagram, Discord, arquivo…)": "Вставьте URL (YouTube, TikTok, Instagram, Discord, файл…)",
